public class Methods {
    static int add(int a, int b) {          // static: no object needed
        return a + b;
    }
    static int add(int a, int b, int c) {    // overload: different parameter count
        return a + b + c;
    }
    static int sum(int... numbers) {         // varargs
        int total = 0;
        for (int n : numbers) total += n;
        return total;
    }
    static long factorial(int n) {           // recursion
        if (n <= 1) return 1;
        return n * factorial(n - 1);
    }

    public static void main(String[] args) {
        System.out.println(add(2, 3) + " " + add(2, 3, 4) + " " + sum(1, 2, 3, 4) + " " + factorial(5));
    }
}
